// Hand-written `hono` stub for the flowatlas fixture suite.
//
// The receiver's type is the only signal that separates an application from any
// other object with a method called `get`, and `Context.get` is written on a
// receiver from this same package, so the adapter checks the type name as well.
// Both are declared here for that reason. Only the shapes it matches on exist.

export type Next = () => Promise<void>;

/**
 * What validators in front of a handler checked, by where in the request they
 * looked. A route with `zValidator('json', schema)` in front of its handler
 * hands it a context whose `req.valid('json')` is the schema's type.
 */
export interface Input {
  out?: { json?: unknown; query?: unknown; param?: unknown; header?: unknown; form?: unknown };
}

export declare class HonoRequest<I extends Input = {}> {
  param(name: string): string;
  json<T = any>(): Promise<T>;
  valid<K extends keyof NonNullable<I['out']>>(target: K): NonNullable<I['out']>[K];
}

/** What a handler is handed. Its `get` reads a value, and declares no route. */
export declare class Context<I extends Input = {}> {
  readonly req: HonoRequest<I>;
  get(key: string): any;
  set(key: string, value: unknown): void;
  json(value: unknown, status?: number): Response;
  text(value: string): Response;
}

export type Handler<I extends Input = {}> = (c: Context<I>, next?: Next) => unknown;
export type MiddlewareHandler<I extends Input = {}> = (c: Context<I>, next: Next) => unknown;

export declare class Hono {
  get(path: string, ...handlers: Handler[]): Hono;
  post<I extends Input>(path: string, validator: MiddlewareHandler<I>, handler: Handler<I>): Hono;
  post(path: string, ...handlers: Handler[]): Hono;
  put<I extends Input>(path: string, validator: MiddlewareHandler<I>, handler: Handler<I>): Hono;
  put(path: string, ...handlers: Handler[]): Hono;
  patch(path: string, ...handlers: Handler[]): Hono;
  delete(path: string, ...handlers: Handler[]): Hono;
  options(path: string, ...handlers: Handler[]): Hono;
  head(path: string, ...handlers: Handler[]): Hono;
  all(path: string, ...handlers: Handler[]): Hono;
  on(method: string | string[], path: string, ...handlers: Handler[]): Hono;
  use(path: string, ...handlers: MiddlewareHandler[]): Hono;
  route(path: string, app: Hono): Hono;
  basePath(path: string): Hono;
  notFound(handler: Handler): Hono;
  fetch(request: Request): Promise<Response>;
}
